import sys

def solution():
    s = sys.stdin.read().strip()
    if not s:
        print("true")
        return
    cmin, cmax = 0, 0
    for char in s:
        if char == "(":
            cmax += 1
            cmin += 1
        elif char == ")":
            cmax -= 1
            cmin = max(cmin - 1, 0)
        elif char == "*":
            cmax += 1
            cmin = max(cmin - 1, 0)
        if cmax < 0:
            print("false")
            return
    print("true" if cmin == 0 else "false")

solution()

import sys
from collections import OrderedDict

def solution():
    lines = sys.stdin.read().splitlines()
    if not lines: return
    k, n = map(int, lines[0].split())
    cache = OrderedDict()
    for i in range(1, n + 1):
        parts = lines[i].split()
        op = parts[0]
        if op == "GET":
            key = int(parts[1])
            if key in cache:
                cache.move_to_end(key)
                print(cache[key])
            else:
                print(-1)
        elif op == "PUT":
            key = int(parts[1])
            val = int(parts[2])
            if key in cache:
                cache.move_to_end(key)
            cache[key] = val
            if len(cache) > k:
                cache.popitem(last=False)

solution()

